CREATE SCHEMA IF NOT EXISTS catalog AUTHORIZATION spms_owner;

CREATE TABLE catalog.service (
    service_id                     uuid NOT NULL DEFAULT core.uuid_v7(),
    tenant_id                      uuid NOT NULL,
    code                           text NOT NULL,
    name                           text NOT NULL,
    catalog_type                   text NOT NULL DEFAULT 'Service',
    category_code                  text,
    duration_minutes               integer NOT NULL,
    pre_buffer_minutes             integer NOT NULL DEFAULT 0,
    post_buffer_minutes            integer NOT NULL DEFAULT 0,
    base_price_minor               bigint NOT NULL DEFAULT 0,
    currency_code                  char(3) NOT NULL,
    requires_intake                boolean NOT NULL DEFAULT true,
    minimum_guest_age              smallint,
    tax_code                       text,
    revenue_center_code            text,
    status                         text NOT NULL DEFAULT 'Active',
    effective_from                 timestamptz NOT NULL DEFAULT now(),
    effective_to                   timestamptz,
    source_system                  text NOT NULL DEFAULT 'Spa',
    source_key                     text,
    version                        integer NOT NULL DEFAULT 1,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    created_by                     uuid,
    updated_at                     timestamptz NOT NULL DEFAULT now(),
    updated_by                     uuid,
    correlation_id                 text,
    CONSTRAINT service_pkey PRIMARY KEY (service_id),
    CONSTRAINT service_catalog_type_ck CHECK (catalog_type IN ('Service', 'AddOn', 'Package', 'Class')),
    CONSTRAINT service_duration_minutes_ck CHECK (duration_minutes > 0),
    CONSTRAINT service_pre_buffer_minutes_ck CHECK (pre_buffer_minutes >= 0),
    CONSTRAINT service_post_buffer_minutes_ck CHECK (post_buffer_minutes >= 0),
    CONSTRAINT service_base_price_minor_ck CHECK (base_price_minor >= 0),
    CONSTRAINT service_currency_code_ck CHECK (currency_code ~ '^[A-Z]{3}$'),
    CONSTRAINT service_minimum_guest_age_ck CHECK (minimum_guest_age BETWEEN 0 AND 120),
    CONSTRAINT service_version_ck CHECK (version >= 1),
    CONSTRAINT service_tenant_identity_uq UNIQUE (tenant_id, service_id),
    CONSTRAINT service_status_known CHECK (status IN ('Active', 'Inactive', 'Retired')),
    CONSTRAINT service_effective_range_ck CHECK (effective_to IS NULL OR effective_to > effective_from),
    CONSTRAINT service_code_uq UNIQUE (tenant_id, code)
);
COMMENT ON TABLE catalog.service IS 'Tenant-wide service master. Booking always freezes the service_version it used. [§53.2 Catalog; treatment_service_master.schema.json]';
COMMENT ON COLUMN catalog.service.duration_minutes IS 'a zero duration would make end_at = start_at and disable CON-002 for the service';

CREATE TABLE catalog.service_version (
    service_version_id             uuid NOT NULL DEFAULT core.uuid_v7(),
    tenant_id                      uuid NOT NULL,
    service_id                     uuid NOT NULL,
    version_number                 integer NOT NULL,
    service_name                   text NOT NULL,
    internal_name                  text,
    short_description              text,
    full_description               text,
    duration_minutes               integer NOT NULL,
    minimum_duration_minutes       integer,
    maximum_duration_minutes       integer,
    pre_buffer_minutes             integer NOT NULL DEFAULT 0,
    post_buffer_minutes            integer NOT NULL DEFAULT 0,
    price_minor                    bigint NOT NULL,
    currency_code                  char(3) NOT NULL,
    capacity_minimum               smallint NOT NULL DEFAULT 1,
    capacity_maximum               smallint NOT NULL DEFAULT 1,
    online_bookable                boolean NOT NULL DEFAULT false,
    deposit_required               boolean NOT NULL DEFAULT false,
    cancellation_policy_code       text,
    late_arrival_policy_code       text,
    intake_requirement_codes       text[] NOT NULL DEFAULT '{}',
    consent_requirement_codes      text[] NOT NULL DEFAULT '{}',
    minimum_guest_age              smallint,
    maximum_guest_age              smallint,
    published_at                   timestamptz,
    published_by                   uuid,
    status                         text NOT NULL DEFAULT 'Draft',
    effective_from                 timestamptz NOT NULL DEFAULT now(),
    effective_to                   timestamptz,
    source_system                  text NOT NULL DEFAULT 'Spa',
    source_key                     text,
    version                        integer NOT NULL DEFAULT 1,
    created_at                     timestamptz NOT NULL DEFAULT now(),
    created_by                     uuid,
    updated_at                     timestamptz NOT NULL DEFAULT now(),
    updated_by                     uuid,
    correlation_id                 text,
    CONSTRAINT service_version_pkey PRIMARY KEY (service_version_id),
    CONSTRAINT service_version_version_number_ck CHECK (version_number >= 1),
    CONSTRAINT service_version_duration_minutes_ck CHECK (duration_minutes > 0),
    CONSTRAINT service_version_pre_buffer_minutes_ck CHECK (pre_buffer_minutes >= 0),
    CONSTRAINT service_version_post_buffer_minutes_ck CHECK (post_buffer_minutes >= 0),
    CONSTRAINT service_version_price_minor_ck CHECK (price_minor >= 0),
    CONSTRAINT service_version_currency_code_ck CHECK (currency_code ~ '^[A-Z]{3}$'),
    CONSTRAINT service_version_capacity_minimum_ck CHECK (capacity_minimum >= 1),
    CONSTRAINT service_version_version_ck CHECK (version >= 1),
    CONSTRAINT service_version_tenant_identity_uq UNIQUE (tenant_id, service_version_id),
    CONSTRAINT service_version_status_known CHECK (status IN ('Draft', 'Published', 'Retired')),
    CONSTRAINT service_version_effective_range_ck CHECK (effective_to IS NULL OR effective_to > effective_from),
    CONSTRAINT service_version_capacity_range CHECK (capacity_maximum >= capacity_minimum),
    CONSTRAINT service_version_duration_range CHECK ((minimum_duration_minutes IS NULL OR minimum_duration_minutes <= duration_minutes) AND (maximum_duration_minutes IS NULL OR maximum_duration_minutes >= duration_minutes)),
    CONSTRAINT service_version_age_range CHECK (maximum_guest_age IS NULL OR minimum_guest_age IS NULL OR maximum_guest_age >= minimum_guest_age),
    CONSTRAINT service_version_published_complete CHECK (status <> 'Published' OR (published_at IS NOT NULL AND published_by IS NOT NULL)),
    CONSTRAINT service_version_number_uq UNIQUE (tenant_id, service_id, version_number)
);
COMMENT ON TABLE catalog.service_version IS 'Published, effective-dated snapshot of a service. Appointments reference the version booked. [treatment_service_master.schema.json; DEC-005]';

